/// A cell's colour: the pixie's colour mixed toward `toward` by `amount`, per RGB
/// channel and rounded, drawn at `opacity`.
public struct MascotTone: Sendable, Equatable {
    public let toward: String
    public let amount: Double
    public let opacity: Double
}

/// How "+" (shade), "o" (light) and "*" (wing) cells derive from the pixie's colour (B89).
